class Solution {
public:
    int shoppingOffers(vector<int>& price, vector<vector<int>>& special, vector<int>& needs) {
        int n = price.size();
        // Keep only offers that are strictly cheaper than buying items individually
        vector<vector<int>> filtered;
        for (auto& s : special) {
            int sum = 0;
            for (int i = 0; i < n; i++) sum += s[i] * price[i];
            if (s[n] < sum) filtered.push_back(s);
        }

        int sz = 1;
        for (int i = 0; i < n; i++) sz *= 11;
        vector<int> memo(sz, -1);

        int pw[7];
        pw[0] = 1;
        for (int i = 1; i <= n; i++) pw[i] = pw[i - 1] * 11;

        function<int(int)> dp = [&](int state) -> int {
            if (memo[state] != -1) return memo[state];

            int need[6];
            int tmp = state;
            int total = 0;
            for (int i = 0; i < n; i++) {
                need[i] = tmp % 11;
                tmp /= 11;
                total += need[i] * price[i];
            }

            int best = total;
            for (auto& s : filtered) {
                int newState = 0;
                bool ok = true;
                for (int i = 0; i < n; i++) {
                    int r = need[i] - s[i];
                    if (r < 0) { ok = false; break; }
                    newState += r * pw[i];
                }
                if (!ok) continue;
                int sub = dp(newState);
                best = min(best, s[n] + sub);
            }

            memo[state] = best;
            return best;
        };

        int init = 0;
        for (int i = 0; i < n; i++) init += needs[i] * pw[i];
        return dp(init);
    }
};
